"""Render docs/AUTHORIZATION_MATRIX.md from the live policy (authz.decide) over the seed corpus."""

from __future__ import annotations

from pathlib import Path

from inkfall.authz import DocACL, decide
from inkfall.corpus import load_seed_corpus
from inkfall.identities import load_directory

ROOT = Path(__file__).resolve().parents[1]


def main() -> None:
    d = load_directory()
    docs = load_seed_corpus(d)
    users = list(d.users.values())
    lines = ["# Authorization matrix", "",
             "_Generated by `scripts/render_authz_matrix.py` from `src/inkfall/authz.py` and the seed corpus. "
             "`Y` = may read; `·` = denied. The same function gates every API path; tests/test_isolation.py "
             "checks the API against it._", "",
             "## Rule", "",
             "A user may read a document version only if **all** hold (deny wins, unknown labels fail closed):", "",
             "1. same tenant;", "2. version classification <= user clearance (public < internal < confidential < restricted);",
             "3. the user shares at least one ACL group with the version;", "4. the user is not on the version's ethical wall;",
             "5. the document is not deleted.", "",
             "Roles (`admin`, `reviewer`, `counsel`) grant *functions* only: ingest/delete/audit view, approving briefs. "
             "They never grant read access. Temporal rules (in force on the as-of date) are applied after authorization.", "",
             "## Function permissions", "",
             "| Function | Who | Enforced in |", "|---|---|---|",
             "| Read/search/cite/compare/export a version | ACL rule above | `access.authorized_versions`, `access.get_authorized_version` |",
             "| Ingest upload, delete document, quarantine list, records registry | role `admin`, own tenant only | `api.require_role` + tenant from session |",
             "| Audit log view | role `admin` or `reviewer`, own tenant | `api.audit_view` |",
             "| Approve / reject a brief | role `reviewer`, not the author, must be able to read every cited version | `api.decide_summary` |",
             "| Release an approved brief (local outbox) | author or approver; status must be `approved` | `api.release_summary` |",
             "| Review labels | any user, only on versions they can read; reviewers see the tenant's labels | `api.create_review`, `api.list_reviews` |",
             "| Evaluation console | any user; per-question rows limited to own tenant, unreadable refs hidden | `api.eval_report` |", "",
             "## Identities", "", "| User | Tenant | Roles | Groups | Clearance |", "|---|---|---|---|---|"]
    for u in users:
        lines.append(f"| {u.username} | {u.tenant} | {', '.join(u.roles)} | {', '.join(u.groups)} | {u.clearance} |")
    lines += ["", "## Matrix (document version x identity)", ""]
    for t in d.tenants.values():
        tdocs = [x for x in docs if x.tenant == t.id]
        lines += [f"### {t.name} (fictional)", "",
                  "| Version | Class | Groups | Wall | " + " | ".join(u.username for u in users) + " |",
                  "|---|---|---|---|" + "---|" * len(users)]
        for x in tdocs:
            acl = DocACL(x.tenant, x.classification, tuple(x.acl_groups), tuple(x.ethical_wall))
            cells = ["Y" if decide(u, acl, d).allowed else "·" for u in users]
            lines.append(f"| {x.ref} | {x.classification} | {', '.join(x.acl_groups)} | "
                         f"{', '.join(x.ethical_wall) or ''} | " + " | ".join(cells) + " |")
        lines.append("")
    readable = sum(1 for x in docs for u in users if decide(u, DocACL(x.tenant, x.classification, tuple(x.acl_groups),
                                                                        tuple(x.ethical_wall)), d).allowed)
    lines += [f"Totals: {len(docs)} versions x {len(users)} identities = {len(docs) * len(users)} decisions; "
              f"{readable} allowed, {len(docs) * len(users) - readable} denied.", ""]
    (ROOT / "docs" / "AUTHORIZATION_MATRIX.md").write_text("\n".join(lines))
    print("rendered docs/AUTHORIZATION_MATRIX.md")


if __name__ == "__main__":
    main()
